// Manual bindings for types that bindgen cannot handle correctly

use super::bindings::*;

/// Manual definition of WINHTTP_CONNECTION_INFO
/// This struct cannot be automatically generated by bindgen because
/// it has packing attributes that conflict with the alignment requirements
/// of SOCKADDR_STORAGE
#[repr(C)]
#[derive(Debug, Copy, Clone)]
#[allow(non_snake_case)]
pub struct WINHTTP_CONNECTION_INFO {
    pub cbSize: DWORD,
    pub LocalAddress: SOCKADDR_STORAGE,
    pub RemoteAddress: SOCKADDR_STORAGE,
}

impl Default for WINHTTP_CONNECTION_INFO {
    fn default() -> Self {
        Self {
            cbSize: std::mem::size_of::<Self>() as DWORD,
            LocalAddress: unsafe { std::mem::zeroed() },
            RemoteAddress: unsafe { std::mem::zeroed() },
        }
    }
}